@extends('vendor.layout') @section('title','Gemini AI') @section('content')<div class="container"><h1>Gemini AI Assistant</h1><div class="panel"><h2>AI Product Builder</h2><form id="vAi"><textarea id="vAiInput" rows="4" style="width:100%" placeholder="Example: Wireless earbuds, ANC, black, Bluetooth 5.4..."></textarea><button type="submit">Generate Product Content</button></form><pre id="vAiOut" style="white-space:pre-wrap"></pre></div><div class="panel"><p>AI activity for your vendor account.</p><table><tr><th>Action</th><th>Created</th></tr>@foreach($logs as $l)<tr><td>{{$l->action ?? $l->type ?? 'AI request'}}</td><td>{{$l->created_at}}</td></tr>@endforeach</table>{{$logs->links()}}</div></div><script>document.getElementById("vAi")?.addEventListener("submit",async e=>{e.preventDefault();let o=document.getElementById("vAiOut");o.textContent="Generating...";let r=await fetch("{{route("vendor.ai.product-builder")}}",{method:"POST",headers:{"Content-Type":"application/json","X-CSRF-TOKEN":"{{csrf_token()}}"},body:JSON.stringify({input:document.getElementById("vAiInput").value})});let j=await r.json();o.textContent=JSON.stringify(j.data||j,null,2)});</script>@endsection